package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock is the time source used by the limiter.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu     sync.Mutex
	clock  Clock
	rate   float64 // tokens per second
	burst  float64
	tokens float64
	last   time.Time
}

// New creates a Limiter allowing rate tokens per second with the given burst.
// A nil clock uses the system clock.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be positive")
	}
	if burst <= 0 {
		return nil, errors.New("ratelimit: burst must be positive")
	}
	if clock == nil {
		clock = realClock{}
	}
	now := clock.Now()
	return &Limiter{
		clock:  clock,
		rate:   rate,
		burst:  float64(burst),
		tokens: float64(burst),
		last:   now,
	}, nil
}

// AllowN reports whether n tokens are available, consuming them if so.
// n == 0 always returns true; n < 0 always returns false.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	if n == 0 {
		return true
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill()
	if l.tokens >= float64(n) {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether one token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// Tokens returns the current estimated token count.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill()
	return l.tokens
}

func (l *Limiter) refill() {
	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed <= 0 {
		return
	}
	l.tokens += elapsed * l.rate
	if l.tokens > l.burst {
		l.tokens = l.burst
	}
	l.last = now
}
