package ratelimit

import (
	"sync"
	"testing"
	"time"
)

type fakeClock struct {
	mu sync.Mutex
	t  time.Time
}

func newFakeClock() *fakeClock {
	return &fakeClock{t: time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)}
}

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.t
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.t = c.t.Add(d)
}

func TestNewValidation(t *testing.T) {
	clk := newFakeClock()
	tests := []struct {
		name  string
		rate  float64
		burst int
		clock Clock
		want  bool
	}{
		{"valid", 10, 5, clk, true},
		{"nil clock uses system", 10, 5, nil, true},
		{"zero rate", 0, 5, clk, false},
		{"negative rate", -1, 5, clk, false},
		{"zero burst", 10, 0, clk, false},
		{"negative burst", 10, -1, clk, false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			l, err := New(tt.rate, tt.burst, tt.clock)
			if tt.want && err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if !tt.want && err == nil {
				t.Fatal("expected error, got nil")
			}
			if tt.want && l == nil {
				t.Fatal("expected limiter, got nil")
			}
		})
	}
}

