			name:  "burst then deny",
			rate:  1,
			burst: 3,
			steps: []step{{0, 1}, {0, 1}, {0, 1}, {0, 1}},
			expect: []bool{true, true, true, false},
		},
		{
			name:  "refill over time",
			rate:  10,
