// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock is the injectable time source used by the limiter.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu      sync.Mutex
	clock   Clock
	capacity float64
	rate    float64 // tokens per second
	tokens  float64
	last    time.Time
}

// New creates a Limiter with the given burst capacity and refill rate.
// The clock may be nil, in which case the system clock is used.
func New(capacity int, refillPerSecond float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be positive")
	}
	if refillPerSecond <= 0 {
		return nil, errors.New("ratelimit: refill rate must be positive")
	}
	if clock == nil {
		clock = realClock{}
	}
	now := clock.Now()
	return &Limiter{
		clock:   clock,
		capacity: float64(capacity),
		rate:    refillPerSecond,
		tokens:  float64(capacity),
		last:    now,
	}, nil
}

func (l *Limiter) refillLocked(now time.Time) {
	elapsed := now.Sub(l.last).Seconds()
	if elapsed <= 0 {
		return
	}
	l.tokens += elapsed * l.rate
	if l.tokens > l.capacity {
		l.tokens = l.capacity
	}
	l.last = now
}

// AllowN reports whether n tokens can be consumed, consuming them if so.
// Non-positive n is always allowed and consumes nothing.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.clock.Now()
	l.refillLocked(now)
	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Allow reports whether one token can be consumed.
func (l *Limiter) Allow() bool {
	return l.AllowN(1)
}

// Tokens returns the current estimated available tokens.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refillLocked(l.clock.Now())
	return l.tokens
}
