type fakeClock struct {
	mu sync.Mutex
	t  time.Time
}

func newFakeClock(t time.Time) *fakeClock { return &fakeClock{t: t} }

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.t
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.t = c.t.Add(d)
}

func TestNewValidation(t *testing.T) {
	clock := newFakeClock(time.Unix(0, 0))
	tests := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"valid", 10, 2, clock, false},
		{"nil clock uses system", 10, 2, nil, false},
		{"zero capacity", 0, 2, clock, true},
		{"negative capacity", -1, 2, clock, true},
		{"zero rate", 10, 0, clock, true},
		{"negative rate", 10, -1, clock, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			l, err := New(tt.capacity, tt.rate, tt.clock)
			if (err != nil) != tt.wantErr {
				t.Fatalf("New() error = %v, wantErr %v", err, tt.wantErr)
			}
			if !tt.wantErr && l == nil {
				t.Fatal("New() returned nil limiter")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	base := time.Unix(1_700_000_000, 0)
	tests := []struct {
		name    string
		cap     int
		rate    float64
		advance time.Duration
		n       int
		want    bool
	}{
		{"full bucket allows burst", 5, 1, 0, 5, true},
		{"full bucket rejects over capacity", 5, 1, 0, 6, false},
		{"refill after one second", 5, 2, time.Second, 2, true},
		{"refill capped at capacity", 5, 10, time.Second, 5, true},
		{"zero tokens always allowed", 5, 1, 0, 0, true},
		{"negative tokens always allowed", 5, 1, 0, -3, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			clock := newFakeClock(base)
			l, err := New(tt.cap, tt.rate, clock)
			if err != nil {
				t.Fatal(err)
			}
			clock.Advance(tt.advance)
			if got := l.AllowN(tt.n); got != tt.want {
				t.Fatalf("AllowN(%d) = %v, want %v", tt.n, got, tt.want)
			}
		})
	}
}

func TestAllowNConsumesTokens(t *testing.T) {
	clock := newFakeClock(time.Unix(0, 0))
	l, err := New(3, 1, clock)
	if err != nil {
		t.Fatal(err)
	}
	if !l.AllowN(2) {
		t.Fatal("first AllowN(2) failed")
	}
	if l.AllowN(2) {
		t.Fatal("second AllowN(2) should fail")
	}
	if !l.AllowN(1) {
		t.Fatal("AllowN(1) should succeed")
	}
	if l.AllowN(1) {
		t.Fatal("bucket should be empty")
	}
}

func TestConcurrentAllowN(t *testing.T) {
	clock := newFakeClock(time.Unix(0, 0))
	l, err := New(100, 0, clock) // rate must be positive; use tiny rate
	if err == nil {
		t.Fatal("expected error for zero rate")
	}
	l, err = New(100, 1, clock)
	if err != nil {
		t.Fatal(err)
	}
	var wg sync.WaitGroup
	var mu sync.Mutex
	allowed := 0
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
